with flattened as (select id, tag from carts lateral view explode(coupon_codes) e as tag) select tag, count(case when tag = 'SPRING10' then 1 end) as spring10_count, count(*) as event_count, size(collect_set(tag)) as num_tags, count_if(tag = 'VIP') as vip_events, count(case when tag = 'BUNDLE' then 1 end) as bundle_count, size(collect_set(tag)) as num_tags_2 from flattened group by 1 having size(collect_set(tag)) > 1 order by spring10_count desc nulls first
